const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let idx = 0;
const N = Number(data[idx++]);
const p = new Int32Array(N + 1);
p[1] = 0;
for (let i = 2; i <= N; i++) {
    p[i] = Number(data[idx++]);
}
const Q = Number(data[idx++]);

const children = Array.from({ length: N + 1 }, () => []);
for (let i = 2; i <= N; i++) {
    children[p[i]].push(i);
}

const tin = new Int32Array(N + 1);
const tout = new Int32Array(N + 1);
const nodeAtTin = new Int32Array(N + 1);
let timer = 0;
const stack = [1];
const visited = new Uint8Array(N + 1);
while (stack.length > 0) {
    const u = stack[stack.length - 1];
    if (!visited[u]) {
        visited[u] = 1;
        tin[u] = ++timer;
        nodeAtTin[timer] = u;
        const ch = children[u];
        for (let i = ch.length - 1; i >= 0; i--) {
            stack.push(ch[i]);
        }
    } else {
        stack.pop();
        tout[u] = timer;
    }
}

const LOG = 18;
const up = new Array(LOG);
up[0] = new Int32Array(N + 1);
for (let i = 1; i <= N; i++) up[0][i] = p[i];
for (let j = 1; j < LOG; j++) {
    up[j] = new Int32Array(N + 1);
    const prev = up[j - 1];
    const curr = up[j];
    for (let i = 1; i <= N; i++) {
        curr[i] = prev[prev[i]];
    }
}

function kthAncestor(u, k) {
    if (k === 0) return u;
    for (let j = 0; j < LOG; j++) {
        if (k & (1 << j)) {
            u = up[j][u];
        }
    }
    return u;
}

class BIT {
    constructor(n) {
        this.n = n;
        this.tree = new Int32Array(n + 2);
    }
    add(i, delta) {
        for (; i <= this.n; i += i & -i) this.tree[i] += delta;
    }
    sum(i) {
        let s = 0;
        for (; i > 0; i -= i & -i) s += this.tree[i];
        return s;
    }
    findKth(k) {
        let idx = 0;
        let bitMask = 1;
        while (bitMask << 1 <= this.n) bitMask <<= 1;
        for (let d = bitMask; d > 0; d >>= 1) {
            const next = idx + d;
            if (next <= this.n && this.tree[next] < k) {
                idx = next;
                k -= this.tree[next];
            }
        }
        return idx + 1;
    }
}

const bit = new BIT(N);
const out = [];

for (let q = 0; q < Q; q++) {
    const type = Number(data[idx++]);
    if (type === 1) {
        const u = Number(data[idx++]);
        const k = Number(data[idx++]);
        let c = bit.sum(tin[u]);
        let v = -1;
        if (c > 0) {
            const rootTin = bit.findKth(c);
            const root = nodeAtTin[rootTin];
            if (tout[root] >= tin[u]) {
                v = root;
            }
        }
        let ans;
        if (v !== -1) {
            if (u === v) {
                ans = kthAncestor(u, k);
            } else {
                if (k === 1) {
                    ans = v;
                } else {
                    ans = kthAncestor(v, k - 1);
                }
            }
        } else {
            ans = kthAncestor(u, k);
        }
        out.push(ans);
    } else {
        const v = Number(data[idx++]);
        let c = bit.sum(tin[v]);
        if (c > 0) {
            const rootTin = bit.findKth(c);
            const root = nodeAtTin[rootTin];
            if (tout[root] >= tin[v]) {
                continue;
            }
        }
        const L = tin[v];
        const R = tout[v];
        const cL = bit.sum(L - 1);
        while (true) {
            const nextTin = bit.findKth(cL + 1);
            if (nextTin > R) break;
            bit.add(nextTin, -1);
        }
        bit.add(L, 1);
    }
}

console.log(out.join('\n'));
